import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import {
  GetRecentCalls,
  GetCachedAvatar,
  MakeCall,
  MakeGroupCall,
} from "../../../bindings/github.com/lugvitc/whats4linux/api/api.js"
import { EventsOn } from "../../lib/wailsRuntime"
import { formatDateSeparator } from "../../lib/utils"
import { useUIStore } from "../../store/useUIStore"
import { useContactStore } from "../../store/useContactStore"

/**
 * Mirror of the generated `store.CallLogEntry` shape. The binding module is
 * regenerated by the build gate, so the field names here intentionally match
 * the Go JSON tags exactly and nothing is imported from models.ts by hand.
 */
interface CallLogEntry {
  call_id: string
  peer_jid: string
  group_jid: string
  is_incoming: boolean
  is_video: boolean
  result: string
  /** Unix seconds. */
  started_at: number
  duration_secs: number
  /** "history" | "appstate" | "local" */
  source: string
}

const FOCUS_RING =
  "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-(--color-focus-ring)"

const JID_RE = /^[A-Za-z0-9._@-]+@[A-Za-z0-9.-]+$/

/** JIDs are only ever store keys / RPC arguments, never raw display text. */
function safeJid(value: unknown): string {
  if (typeof value !== "string") return ""
  const jid = value.trim()
  return jid.length <= 256 && JID_RE.test(jid) ? jid : ""
}

function safeText(value: unknown): string {
  if (typeof value !== "string") return ""
  return value.replace(/[\u0000-\u001f\u007f]/g, "").trim().slice(0, 120)
}

const RESULT_LABELS: Record<string, string> = {
  answered: "Answered",
  accepted: "Answered",
  connected: "Answered",
  // HyperMeow's CallResult enum .String() values (history/appstate rows).
  acceptedelsewhere: "Answered elsewhere",
  missed: "Missed",
  missed_call: "Missed",
  no_answer: "Missed",
  timeout: "Missed",
  timeouted: "Missed",
  rejected: "Rejected",
  declined: "Rejected",
  busy: "Busy",
  unavailable: "Unavailable",
  invalid: "Invalid",
  upcoming: "Upcoming",
  failed: "Failed",
  abandoned: "Abandoned",
  ongoing: "Ongoing",
  canceled: "Canceled",
  cancelled: "Canceled",
  incoming: "Incoming",
  outgoing: "Outgoing",
}

function resultLabel(raw: string): string {
  const key = raw.trim().toLowerCase().replace(/[\s-]+/g, "_")
  return RESULT_LABELS[key] ?? (raw || "Call")
}

function isMissed(raw: string): boolean {
  const key = raw.trim().toLowerCase()
  return (
    key.includes("miss") ||
    key.includes("no_answer") ||
    key === "timeout" ||
    key === "timeouted"
  )
}

function formatDuration(secs: unknown): string {
  if (typeof secs !== "number" || !Number.isFinite(secs) || secs <= 0) return ""
  const total = Math.floor(secs)
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`
}

function formatTime(unixSeconds: unknown): string {
  if (typeof unixSeconds !== "number" || !Number.isFinite(unixSeconds)) return ""
  const date = new Date(unixSeconds * 1000)
  if (Number.isNaN(date.getTime())) return ""
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
}

function dayKey(unixSeconds: unknown): string {
  if (typeof unixSeconds !== "number" || !Number.isFinite(unixSeconds)) return ""
  const date = new Date(unixSeconds * 1000)
  if (Number.isNaN(date.getTime())) return ""
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`
}

function PhoneGlyph({ className = "h-5 w-5" }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" className={className} fill="currentColor" aria-hidden="true">
      <path d="M6.6 3.2A1.6 1.6 0 0 0 5.02 4.54l-.72 4.1a1.6 1.6 0 0 0 .46 1.4l2.1 2.05a13.9 13.9 0 0 0 5.05 5.05l2.05 2.1a1.6 1.6 0 0 0 1.4.46l4.1-.72a1.6 1.6 0 0 0 1.34-1.58v-1.9a1.6 1.6 0 0 0-1.75-1.59l-2.4.27a1.6 1.6 0 0 0-1.36.98l-.42 1.02a10.7 10.7 0 0 1-3.4-3.4l1.02-.42a1.6 1.6 0 0 0 .98-1.36l.27-2.4A1.6 1.6 0 0 0 12.2 4.8h-1.9a1.6 1.6 0 0 0-1.6-1.6H6.6z" />
    </svg>
  )
}

function ChatGlyph() {
  return (
    <svg
      viewBox="0 0 24 24"
      className="h-5 w-5"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M4.5 5.75h15a1.25 1.25 0 0 1 1.25 1.25v8a1.25 1.25 0 0 1-1.25 1.25H10l-4 3v-3H4.5A1.25 1.25 0 0 1 3.25 15V7A1.25 1.25 0 0 1 4.5 5.75z" />
    </svg>
  )
}

function DirectionGlyph({ incoming, missed }: { incoming: boolean; missed: boolean }) {
  return (
    <span
      aria-hidden="true"
      className={
        missed
          ? "text-red-500 dark:text-red-400"
          : "text-light-muted dark:text-dark-muted"
      }
    >
      <svg viewBox="0 0 24 24" className="h-4 w-4" fill="currentColor">
        {incoming ? (
          <path d="M20 5v6a4 4 0 0 1-4 4H7.8l3.1 3.1-1.4 1.4L4 14.6l5.5-5.5 1.4 1.4L7.8 13H16a2 2 0 0 0 2-2V5h2z" />
        ) : (
          <path d="M20 8.6 14.5 3l-1.4 1.4 3.1 3.1H8a4 4 0 0 0-4 4V19h2v-7.5a2 2 0 0 1 2-2h8.2l-3.1 3.1 1.4 1.4L20 8.6z" />
        )}
      </svg>
    </span>
  )
}

function VideoGlyph() {
  return (
    <svg viewBox="0 0 24 24" className="h-3.5 w-3.5" fill="currentColor" aria-hidden="true">
      <path d="M4 6.5A1.5 1.5 0 0 1 5.5 5h8A1.5 1.5 0 0 1 15 6.5v11a1.5 1.5 0 0 1-1.5 1.5h-8A1.5 1.5 0 0 1 4 17.5v-11zm12 3.1 4.2-2.5a.8.8 0 0 1 1.2.7v7.4a.8.8 0 0 1-1.2.7L16 13.4V9.6z" />
    </svg>
  )
}

function CallRow({
  entry,
  onOpenChat,
}: {
  entry: CallLogEntry
  onOpenChat: (jid: string) => void
}) {
  const addNotification = useUIStore(s => s.addNotification)
  const groupJid = safeJid(entry.group_jid)
  const peerJid = safeJid(entry.peer_jid)
  const jid = groupJid || peerJid
  const isGroup = !!groupJid
  const localPart = safeText(entry.group_jid).split("@")[0] || safeText(entry.peer_jid).split("@")[0]
  const fallbackName = localPart || "Unknown"

  const [name, setName] = useState(fallbackName)
  const [avatar, setAvatar] = useState<string | null>(null)

  // Resolve both the contact name and the cached avatar for this row. `live`
  // guards every late RPC response so a recycled row cannot paint stale data.
  useEffect(() => {
    let live = true
    setName(fallbackName)
    setAvatar(null)
    if (!jid) return () => { live = false }

    void useContactStore
      .getState()
      .getContactName(jid)
      .then(resolved => {
        if (live && resolved) setName(safeText(resolved) || fallbackName)
      })
      .catch(() => {})

    void GetCachedAvatar(jid, false)
      .then(url => {
        if (live) setAvatar(url || null)
      })
      .catch(() => {
        if (live) setAvatar(null)
      })

    return () => {
      live = false
    }
  }, [jid, fallbackName])

  const handleCallBack = () => {
    if (!jid) return
    const call = isGroup ? MakeGroupCall(jid) : MakeCall(jid)
    void call.catch(() => {
      // Static message: backend errors can contain JIDs or paths.
      addNotification("Couldn't start the call. Please try again.", { tone: "error" })
    })
  }

  const handleOpenChat = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation()
    if (jid) onOpenChat(jid)
  }

  const rawResult = safeText(entry.result)
  const missed = isMissed(rawResult)
  const label = resultLabel(rawResult)
  const duration = formatDuration(entry.duration_secs)
  const time = formatTime(entry.started_at)
  const isVideo = !!entry.is_video

  return (
    <div className="group flex items-center gap-3 rounded-xl px-3 py-3 transition-colors hover:bg-black/[0.04] dark:hover:bg-white/[0.06] focus-within:bg-black/[0.04] dark:focus-within:bg-white/[0.06]">
      <span className="flex h-11 w-11 shrink-0 items-center justify-center overflow-hidden rounded-full bg-light-tertiary text-light-muted dark:bg-dark-tertiary dark:text-dark-muted">
        {avatar ? (
          <img
            src={avatar}
            alt=""
            loading="lazy"
            className="h-full w-full object-cover"
            onError={() => setAvatar(null)}
          />
        ) : (
          <PhoneGlyph className="h-5 w-5" />
        )}
      </span>

      <div className="min-w-0 flex-1">
        <div className="flex min-w-0 items-center gap-1.5">
          <span className="truncate text-sm font-medium text-light-text dark:text-dark-text">
            {name}
          </span>
          {isVideo && (
            <span className="shrink-0 text-light-muted dark:text-dark-muted" title="Video call">
              <VideoGlyph />
            </span>
          )}
        </div>
        <div className="mt-0.5 flex min-w-0 items-center gap-1.5 text-[12px] text-light-muted dark:text-dark-muted">
          <DirectionGlyph incoming={!!entry.is_incoming} missed={missed} />
          <span className="shrink-0">{isVideo ? "Video" : "Voice"}</span>
          <span aria-hidden="true" className="shrink-0">
            ·
          </span>
          <span
            className={`truncate ${missed ? "font-medium text-red-500 dark:text-red-400" : ""}`}
          >
            {label}
          </span>
          {duration && (
            <>
              <span aria-hidden="true" className="shrink-0">
                ·
              </span>
              <span className="shrink-0 tabular-nums">{duration}</span>
            </>
          )}
        </div>
      </div>

      {time && (
        <time className="shrink-0 text-[11px] tabular-nums text-light-muted dark:text-dark-muted">
          {time}
        </time>
      )}

      {jid && (
        <div className="flex shrink-0 items-center gap-0.5 opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100">
          <button
            type="button"
            aria-label={`Call back ${name}`}
            title="Call back"
            onClick={handleCallBack}
            className={`rounded-lg p-2 text-light-muted transition-colors hover:bg-black/[0.06] hover:text-light-text dark:text-dark-muted dark:hover:bg-white/[0.08] dark:hover:text-dark-text ${FOCUS_RING}`}
          >
            <PhoneGlyph />
          </button>
          <button
            type="button"
            aria-label={`Open chat with ${name}`}
            title="Open chat"
            onClick={handleOpenChat}
            className={`rounded-lg p-2 text-light-muted transition-colors hover:bg-black/[0.06] hover:text-light-text dark:text-dark-muted dark:hover:bg-white/[0.08] dark:hover:text-dark-text ${FOCUS_RING}`}
          >
            <ChatGlyph />
          </button>
        </div>
      )}
    </div>
  )
}

export function CallsScreen({ onOpenChat }: { onOpenChat: (jid: string) => void }) {
  const [entries, setEntries] = useState<CallLogEntry[]>([])
  const [query, setQuery] = useState("")
  const [loading, setLoading] = useState(true)
  const liveRef = useRef(true)
  const addNotification = useUIStore(s => s.addNotification)

  const load = useCallback(async () => {
    try {
      // The binding is regenerated before this module is built. Cast through
      // unknown so this file never depends on a generated model name.
      const data = (await GetRecentCalls(200)) as unknown as CallLogEntry[]
      if (!liveRef.current) return
      setEntries(Array.isArray(data) ? data : [])
    } catch {
      // Static toast only — never surface the raw backend error.
      if (liveRef.current) addNotification("Couldn't load calls", { tone: "error" })
    } finally {
      if (liveRef.current) setLoading(false)
    }
  }, [addNotification])

  useEffect(() => {
    liveRef.current = true
    void load()
    return () => {
      liveRef.current = false
    }
  }, [load])

  // Same Wails event mechanism every other global event in the app uses.
  useEffect(() => {
    const unsubUpdated = EventsOn("wa:call_log_updated", () => {
      void load()
    })
    const unsubRefresh = EventsOn("wa:chat_list_refresh", () => {
      void load()
    })
    // Also accept a same-window CustomEvent with the same name.
    const onWindowUpdate = () => {
      void load()
    }
    window.addEventListener("wa:call_log_updated", onWindowUpdate)
    return () => {
      unsubUpdated()
      unsubRefresh()
      window.removeEventListener("wa:call_log_updated", onWindowUpdate)
    }
  }, [load])

  const filtered = useMemo(() => {
    const term = query.trim().toLowerCase()
    if (!term) return entries
    return entries.filter(entry => {
      const peer = safeText(entry.peer_jid).toLowerCase()
      const group = safeText(entry.group_jid).toLowerCase()
      const result = safeText(entry.result).toLowerCase()
      return peer.includes(term) || group.includes(term) || result.includes(term)
    })
  }, [entries, query])

  const groups = useMemo(() => {
    const byDay = new Map<string, CallLogEntry[]>()
    for (const entry of filtered) {
      const key = dayKey(entry.started_at)
      const bucket = byDay.get(key) ?? []
      bucket.push(entry)
      byDay.set(key, bucket)
    }
    return [...byDay.entries()]
      .map(([key, items]) => ({
        key,
        label: key ? formatDateSeparator(key) || "Unknown date" : "Unknown date",
        items: [...items].sort(
          (a, b) => Number(b.started_at || 0) - Number(a.started_at || 0),
        ),
      }))
      .sort((a, b) => (a.key < b.key ? 1 : a.key > b.key ? -1 : 0))
  }, [filtered])

  return (
    <div className="flex h-full flex-col bg-light-bg dark:bg-dark-bg">
      <div className="shrink-0 border-b border-gray-200 bg-white px-4 py-3 dark:border-dark-border dark:bg-dark-bg">
        <div className="mb-3 flex items-center gap-2">
          <span className="text-green-ink dark:text-green-light">
            <PhoneGlyph className="h-5 w-5" />
          </span>
          <h1 className="text-lg font-semibold tracking-tight text-light-text dark:text-dark-text">
            Calls
          </h1>
        </div>
        <div className="flex items-center gap-2 rounded-xl bg-light-tertiary px-3 py-2 dark:bg-dark-secondary">
          <svg viewBox="0 0 24 24" className="h-4 w-4 shrink-0 text-light-muted dark:text-dark-muted" fill="currentColor" aria-hidden="true">
            <path d="M9.5 3a6.5 6.5 0 1 0 4.03 11.6l4.44 4.43 1.41-1.41-4.42-4.44A6.5 6.5 0 0 0 9.5 3zm0 2a4.5 4.5 0 1 1 0 9 4.5 4.5 0 0 1 0-9z" />
          </svg>
          <input
            type="search"
            aria-label="Search calls"
            placeholder="Search calls"
            value={query}
            onChange={event => setQuery(event.target.value)}
            className={`w-full bg-transparent text-sm text-light-text placeholder:text-light-muted dark:text-dark-text dark:placeholder:text-dark-muted ${FOCUS_RING}`}
          />
          {query && (
            <button
              type="button"
              aria-label="Clear search"
              title="Clear search"
              onClick={() => setQuery("")}
              className={`shrink-0 rounded-md p-0.5 text-light-muted transition-colors hover:text-light-text dark:text-dark-muted dark:hover:text-dark-text ${FOCUS_RING}`}
            >
              <svg viewBox="0 0 24 24" className="h-3.5 w-3.5" fill="currentColor" aria-hidden="true">
                <path d="M19 6.41 17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
              </svg>
            </button>
          )}
        </div>
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto px-2 py-2">
        {loading ? (
          <div className="px-4 py-10 text-center text-sm text-light-muted dark:text-dark-muted" role="status" aria-live="polite">
            Loading calls…
          </div>
        ) : groups.length === 0 ? (
          <div className="flex flex-col items-center gap-2 px-8 py-16 text-center">
            <span className="flex h-16 w-16 items-center justify-center rounded-full bg-light-tertiary text-light-muted dark:bg-dark-tertiary dark:text-dark-muted">
              <PhoneGlyph className="h-7 w-7" />
            </span>
            <h2 className="text-base font-semibold text-light-text dark:text-dark-text">
              {query ? "No calls found" : "No calls yet"}
            </h2>
            <p className="max-w-xs text-[13px] leading-relaxed text-light-muted dark:text-dark-muted">
              {query
                ? "Try a different name, number or result."
                : "Calls appear here after your first call."}
            </p>
          </div>
        ) : (
          groups.map(group => (
            <section key={group.key || group.label} aria-label={`Calls on ${group.label}`}>
              <h2 className="sticky top-0 z-10 bg-light-bg px-3 py-2 text-[11px] font-semibold uppercase tracking-wide text-light-muted dark:bg-dark-bg dark:text-dark-muted">
                {group.label}
              </h2>
              <ul role="list" className="mb-2">
                {group.items.map((entry, index) => {
                  const key =
                    safeText(entry.call_id) ||
                    `${entry.started_at}-${safeText(entry.peer_jid)}-${safeText(entry.group_jid)}-${index}`
                  return (
                    <li key={key}>
                      <CallRow entry={entry} onOpenChat={onOpenChat} />
                    </li>
                  )
                })}
              </ul>
            </section>
          ))
        )}
      </div>
    </div>
  )
}
